                                      if (n.id === portBlockId) {
                                        return {
                                          ...n,
                                          data: {
                                            ...n.data,
                                            label: newName,
                                            params: {
                                              ...n.data.params,
                                              name: { ...n.data.params.name, value: newName }
                                            }
                                          }
                                        };
                                      }
                                      return n;
                                    }));
                                  }}

handlers.onUpdate:
{(newData) => {
              setNodes(nds => nds.map(n => {
                if (n.id === scopeId) {
                  const updatedParams = { ...n.data.params, ...newData };
                  const updatedData: Record<string, any> = { ...n.data, params: updatedParams };
                  if (newData.numSignals) {
                    const num = Math.max(1, Math.min(8, Number(newData.numSignals.value) || 1));
                    updatedData.ports = Array.from({ length: num }, (_, i) => ({
                      id: `in${i + 1}`,
                      pos: 'left',
                      label: `${i + 1}`,
                      domain: 'Physical',
                      direction: 'in'
                    }));
                    // Prune any incoming edges to channels exceeding new capacity
                    setEdges(eds => eds.filter(e => {
                      if (e.target !== scopeId) return true;
                      // exact scope channel id (same portIdFromHandle path as the assembler), not a suffix strip + digit scrape
                      const portId = portIdFromHandle({ id: scopeId, data: { type: 'scope' } }, e.targetHandle) ?? 'in1';
                      const ch = Number(portId.match(/^in(\d+)$/)?.[1] ?? 1);
                      return ch <= num;
                    }));
                  }
                  return { ...n, data: updatedData };
                }
                return n;
              }));
            }}

